package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.role.RoleService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Gives a selection of people a grade together, in list order (the order they were added). Each person is saved as the
 * person form would save them, keeping their name and terms, so each records its own PERSON_EDITED and rollup lines.
 * One that cannot be saved refuses the whole change: nothing is saved. A viewer changes nothing: none is given it.
 */
@Service
public class BulkGradeService {

    private final PersonRepository people;
    private final PersonService service;
    private final RoleService roles;

    public BulkGradeService(PersonRepository people, PersonService service, RoleService roles) {
        this.people = people;
        this.service = service;
        this.roles = roles;
    }

    /** How many people were given the grade. */
    public record Result(int changed) {
    }

    /** Give each selected person the grade from the from-date (null: the sheet's today). */
    @Transactional
    public Result grade(String sheetId, String user, Collection<Long> ids, String grade, LocalDate from) {
        if (roles.isViewer(sheetId, user)) {
            return new Result(0);
        }
        Set<Long> selected = new HashSet<>(ids);
        List<Person> ordered = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .filter(p -> selected.contains(p.getId()))
                .toList();
        if (ordered.size() != selected.size()) {
            // A selected id not on the sheet.
            Long missing = selected.stream()
                    .filter(id -> ordered.stream().noneMatch(p -> p.getId().equals(id)))
                    .findFirst().orElseThrow();
            throw new PersonNotFoundException(sheetId, missing);
        }
        for (Person person : ordered) {
            service.update(sheetId, user, person.getId(), null, person.getName(), grade, from, person.getTerms(),
                    person.getContact());
        }
        return new Result(ordered.size());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.role.RoleService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Retires a selection of people together from a date, in list order (the order they were added). Each person is
 * retired as the row's retire would retire them, so each records its own PERSON_RETIRED and rollup lines. One that
 * cannot be retired refuses the whole change: nothing is saved. A viewer changes nothing: none is retired.
 */
@Service
public class BulkRetireService {

    private final PersonRepository people;
    private final PersonService service;
    private final RoleService roles;

    public BulkRetireService(PersonRepository people, PersonService service, RoleService roles) {
        this.people = people;
        this.service = service;
        this.roles = roles;
    }

    /** How many people were retired. */
    public record Result(int retired) {
    }

    /** Retire each selected person from the date (null: the sheet's today). */
    @Transactional
    public Result retire(String sheetId, String user, Collection<Long> ids, LocalDate from) {
        if (roles.isViewer(sheetId, user)) {
            return new Result(0);
        }
        Set<Long> selected = new HashSet<>(ids);
        List<Person> ordered = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .filter(p -> selected.contains(p.getId()))
                .toList();
        if (ordered.size() != selected.size()) {
            // A selected id not on the sheet.
            Long missing = selected.stream()
                    .filter(id -> ordered.stream().noneMatch(p -> p.getId().equals(id)))
                    .findFirst().orElseThrow();
            throw new PersonNotFoundException(sheetId, missing);
        }
        for (Person person : ordered) {
            service.retire(sheetId, user, person.getId(), from);
        }
        return new Result(ordered.size());
    }
}
package net.officefloor.hq.app.role;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import java.util.Set;
import org.springframework.http.HttpMethod;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;

/**
 * Refuses every change a viewer asks of a sheet: any request but a read, except loading the sheet, the bulk
 * actions, which go through for a viewer with nothing done and every selected item refused, and generating plan
 * claims or monthly periods, which go through for a viewer with none made.
 */
@Component
public class ViewerInterceptor implements HandlerInterceptor {

    /** The changing requests a viewer may still make: their handlers decide what a viewer gets. */
    private static final Set<String> LET_THROUGH = Set.of("/load", "/claims/bulk-open", "/claims/bulk-settle",
            "/claims/bulk-reassign", "/claims/bulk-redate", "/claims/bulk-void",
            "/people/bulk-grade", "/people/bulk-retire", "/plans/generate", "/periods/generate");

    private final RoleService roles;

    public ViewerInterceptor(RoleService roles) {
        this.roles = roles;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())
                || HttpMethod.OPTIONS.matches(request.getMethod())) {
            return true;
        }
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (LET_THROUGH.stream().anyMatch(path::endsWith)) {
            return true;
        }
        @SuppressWarnings("unchecked")
        Map<String, String> variables = (Map<String, String>) request
                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        String user = request.getHeader("X-User");
        if (variables == null || user == null) {
            return true;
        }
        String sheetId = variables.containsKey("sheetId") ? variables.get("sheetId") : variables.get("id");
        if (sheetId == null) {
            return true;
        }
        if (roles.isViewer(sheetId.trim(), user.trim())) {
            throw new ViewerForbiddenException(sheetId.trim(), user.trim());
        }
        return true;
    }
}
